SET NOCOUNT ON; SET XACT_ABORT ON; SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON; SET ANSI_PADDING ON; SET ANSI_WARNINGS ON; SET ARITHABORT ON; SET CONCAT_NULL_YIELDS_NULL ON; SET NUMERIC_ROUNDABORT OFF;
IF DB_NAME() <> N'TTSmart_Operational_V1_Test' OR NOT EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=2) THROW 58300,N'Thiếu tiền điều kiện.',1;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=3 AND ScriptChecksum='$(ScriptChecksum)') RETURN;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=3) THROW 58301,N'Checksum không khớp.',1;
BEGIN TRANSACTION;
DECLARE @OperationalMigrationLockResult int;
EXEC @OperationalMigrationLockResult = sys.sp_getapplock @Resource=N'TTSmart.Operational.V1.Baseline', @LockMode=N'Exclusive', @LockOwner=N'Transaction', @LockTimeout=60000;
IF @OperationalMigrationLockResult < 0 THROW 58390,N'Không lấy được application lock Operational v1.',1;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=3 AND ScriptChecksum='$(ScriptChecksum)') BEGIN COMMIT; RETURN; END;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=3) THROW 58301,N'Checksum không khớp.',1;
CREATE TABLE dbo.Files (FileId uniqueidentifier NOT NULL CONSTRAINT PK_Files PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, OriginalName nvarchar(512) NOT NULL, Extension nvarchar(20) NOT NULL, MimeType nvarchar(255) NOT NULL, SizeBytes bigint NOT NULL, ContentSha256 char(64) COLLATE Latin1_General_100_BIN2 NOT NULL, Visibility nvarchar(20) COLLATE Latin1_General_100_BIN2 NOT NULL, Status nvarchar(20) COLLATE Latin1_General_100_BIN2 NOT NULL, Version int NOT NULL CONSTRAINT DF_Files_Version DEFAULT 0, SourceCreatedAtUtc datetime2(7) NULL, MigratedAtUtc datetime2(7) NULL, CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_Files_Created DEFAULT SYSUTCDATETIME(), UpdatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_Files_Updated DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_Files_PublicId UNIQUE(PublicId), CONSTRAINT CK_Files_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_Files_Size CHECK(SizeBytes>=0), CONSTRAINT CK_Files_Hash CHECK(ContentSha256 NOT LIKE '%[^0-9A-F]%'), CONSTRAINT CK_Files_Visibility CHECK(Visibility IN(N'Public',N'Private')), CONSTRAINT CK_Files_Status CHECK(Status IN(N'Pending',N'Ready',N'Missing',N'UnlinkedLegacy',N'Deleted')), CONSTRAINT CK_Files_Version CHECK(Version>=0));
CREATE TABLE dbo.FileLocations (FileLocationId uniqueidentifier NOT NULL CONSTRAINT PK_FileLocations PRIMARY KEY, FileId uniqueidentifier NOT NULL, Provider nvarchar(20) NOT NULL, StorageNamespace nvarchar(100) NOT NULL, StorageKey nvarchar(600) NOT NULL, IsPrimary bit NOT NULL CONSTRAINT DF_FileLocations_Primary DEFAULT 0, Status nvarchar(20) NOT NULL, VerifiedAtUtc datetime2(7) NULL, CONSTRAINT FK_FileLocations_File FOREIGN KEY(FileId) REFERENCES dbo.Files(FileId), CONSTRAINT UQ_FileLocations_Provider_Key UNIQUE(Provider,StorageNamespace,StorageKey), CONSTRAINT CK_FileLocations_Provider CHECK(Provider IN(N'Local',N'AzureBlob',N'S3')), CONSTRAINT CK_FileLocations_Namespace CHECK(StorageNamespace<>N'' AND StorageNamespace NOT LIKE N'%:%' AND StorageNamespace NOT LIKE N'%' + NCHAR(92) + N'%' AND StorageNamespace NOT LIKE N'%/%' AND StorageNamespace NOT LIKE N'%..%' AND StorageNamespace NOT LIKE N'%//%'), CONSTRAINT CK_FileLocations_Key CHECK(StorageKey<>N'' AND StorageKey NOT LIKE N'%:%' AND StorageKey NOT LIKE N'%' + NCHAR(92) + N'%' AND StorageKey NOT LIKE N'/%' AND StorageKey NOT LIKE N'./%' AND StorageKey NOT LIKE N'../%' AND StorageKey NOT LIKE N'%//%' AND StorageKey NOT LIKE N'%/./%' AND StorageKey NOT LIKE N'%/../%' AND StorageKey NOT LIKE N'%/.' AND StorageKey NOT LIKE N'%/..'), CONSTRAINT CK_FileLocations_Status CHECK(Status IN(N'Pending',N'Ready',N'Missing',N'Deleted')));
ALTER TABLE dbo.FileLocations DROP CONSTRAINT CK_FileLocations_Namespace;
ALTER TABLE dbo.FileLocations ADD CONSTRAINT CK_FileLocations_Namespace CHECK(dbo.IsValidStoragePath(StorageNamespace,400)=1);
ALTER TABLE dbo.FileLocations DROP CONSTRAINT CK_FileLocations_Key;
ALTER TABLE dbo.FileLocations ADD CONSTRAINT CK_FileLocations_Key CHECK(dbo.IsValidStoragePath(StorageKey,1200)=1);
CREATE UNIQUE INDEX UX_FileLocations_Primary ON dbo.FileLocations(FileId) WHERE IsPrimary=1;
CREATE TABLE dbo.FileAliases (FileAliasId uniqueidentifier NOT NULL CONSTRAINT PK_FileAliases PRIMARY KEY, FileId uniqueidentifier NULL, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, AliasUrl nvarchar(2000) NULL, AliasType nvarchar(30) COLLATE Latin1_General_100_BIN2 NOT NULL, Status nvarchar(20) COLLATE Latin1_General_100_BIN2 NOT NULL, CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_FileAliases_Created DEFAULT SYSUTCDATETIME(), CONSTRAINT FK_FileAliases_File FOREIGN KEY(FileId) REFERENCES dbo.Files(FileId), CONSTRAINT UQ_FileAliases_PublicId UNIQUE(PublicId), CONSTRAINT CK_FileAliases_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_FileAliases_Status CHECK(Status IN(N'Pending',N'Ready',N'Missing',N'UnlinkedLegacy',N'Deleted')));
INSERT dbo.SchemaVersions SELECT NEWID(),N'Operational',3,N'003_CreateFileTables.sql','$(ScriptChecksum)',SYSUTCDATETIME(),ORIGINAL_LOGIN(); COMMIT;
